{"path": "app/api/handlers.py", "file_text": """"Request handlers."""

import json
import subprocess
import sys
from pathlib import Path

from app.services import users

_SLUG_SCRIPT = Path(__file__).resolve().parents[2] / "scripts" / "slug.py"
_MAX_TITLE_LENGTH = 80


def _is_valid_title(title: object) -> bool:
    """Return True when *title* is 1-80 chars and holds an ASCII letter or digit."""
    if not isinstance(title, str):
        return False
    if not 1 <= len(title) <= _MAX_TITLE_LENGTH:
        return False
    return any(char.isascii() and char.isalnum() for char in title)


def _slug_arguments(title: str) -> list[str]:
    """Build the argv passed to scripts/slug.py for *title*."""
    # argparse parses a bare value that begins with "-" as another option, so
    # the "--title=VALUE" form is needed to pass such titles through verbatim.
    if title.startswith("-"):
        return [f"--title={title}"]
    return ["--title", title]


def handle_get_user(params: dict) -> tuple[int, dict]:
    raw = params.get("id")
    if not isinstance(raw, str) or not raw.isdigit():
        return 400, {"error": "invalid id"}
    user = users.get_user(int(raw))
    if user is None:
        return 404, {"error": "not found"}
    return 200, user


def handle_make_slug(params: dict) -> tuple[int, dict]:
    title = params.get("title")
    if not _is_valid_title(title):
        return 400, {"error": "invalid title"}
    result = subprocess.run(
        [sys.executable, str(_SLUG_SCRIPT), *_slug_arguments(title)],
        capture_output=True,
        text=True,
        check=True,
    )
    slug = json.loads(result.stdout)["slug"]
    return 200, {"slug": slug}
"}

